from itertools import product

from rules import POLICY, active_dependencies, acyclic


def solve(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]

    domains = [[-1] + sorted(row["version"] for row in packages[name])
               for name in names]

    for vector in product(*domains):
        selected = {name: version for name, version in zip(names, vector)
                    if version != -1}

        valid = True
        for name, bounds in roots.items():
            version = selected.get(name)
            if version is None or not bounds[0] <= version <= bounds[1]:
                valid = False
                break
        if not valid:
            continue

        for name, version in selected.items():
            if version in blocked.get(name, ()) or (name in pins and
                                                     version != pins[name]):
                valid = False
                break
        if not valid:
            continue

        rows = {
            name: next(row for row in packages[name]
                       if row["version"] == version)
            for name, version in selected.items()
        }
        edges = {name: [] for name in selected}
        for name, row in rows.items():
            for dep in active_dependencies(row, features):
                target = selected.get(dep["name"])
                if target is None or not dep["min"] <= target <= dep["max"]:
                    valid = False
                    break
                edges[name].append(dep["name"])
            if not valid:
                break
        if not valid or not acyclic(edges):
            continue

        reached = set()
        pending = list(roots)
        while pending:
            name = pending.pop()
            if name in reached:
                continue
            reached.add(name)
            pending.extend(edges[name])
        if reached != set(selected):
            continue

        return {"versions": selected}

    return {"error": "unsatisfiable"}

POLICY = {"preference": "minimum", "name_order": "ascending"}


def active_dependencies(row, features):
    return [dependency for dependency in row.get("deps", [])
            if not dependency.get("feature") or
            dependency.get("feature") in features]


def acyclic(edges):
    finished = set()
    active = set()

    def visit(name):
        if name in active:
            return False
        if name in finished:
            return True
        active.add(name)
        for other in edges.get(name, []):
            if not visit(other):
                return False
        active.remove(name)
        finished.add(name)
        return True

    return all(visit(name) for name in edges)
